import Foundation

/// 과학 개념 사전 (초등 → 중학교 → 고등학교 → 대학교)
extension DoitCurriculum {
    static let science: [CurriculumEntry] = [
        // MARK: - 초등

        ce(.elementary, "물질의 상태", ["고체", "solid"], "모양과 부피가 일정한 물질의 상태예요. 다른 그릇에 옮겨 담아도 모양과 부피가 변하지 않고, 손으로 잡을 수 있어요.\n예: 나무 막대, 돌, 플라스틱 블록, 얼음"),
        ce(.elementary, "물질의 상태", ["액체", "liquid"], "흘러내리는 성질이 있어서 담는 그릇에 따라 모양이 바뀌지만, 부피는 변하지 않는 물질의 상태예요. 물 200mL를 컵에 담든 병에 담든 부피는 200mL로 같아요.\n예: 물, 우유, 주스, 식용유"),
        ce(.elementary, "물질의 상태", ["기체", "gas"], "모양과 부피가 일정하지 않고, 담긴 그릇을 항상 가득 채우는 물질의 상태예요. 눈에 잘 보이지 않지만 공간을 차지하고 무게도 있어요. 공기를 더 넣은 공은 넣기 전보다 무거워요.\n예: 공기, 풍선 속 헬륨, 페트병 속 공기"),
        ce(.elementary, "물질의 상태", ["물의 상태 변화", "증발과 끓음"], "물은 얼음(고체), 물(액체), 수증기(기체)로 상태가 바뀌어요. 물 표면에서 물이 천천히 수증기로 변하는 현상을 증발, 물 표면과 물속에서 기포가 생기며 빠르게 수증기로 변하는 현상을 끓음이라고 해요. 물이 얼면 부피가 늘어나요.\n예: 젖은 빨래가 마르는 것은 증발, 냄비 물이 보글보글 끓는 것은 끓음이에요."),
        ce(.elementary, "물질의 상태", ["응결", "condensation"], "공기 중의 수증기가 차가운 물체의 표면에 닿아 물방울로 맺히는 현상이에요. 기체인 수증기가 액체인 물로 상태가 바뀐 것이에요.\n예: 얼음물이 든 컵 바깥쪽에 맺히는 물방울, 추운 날 따뜻한 실내에 들어왔을 때 안경에 서리는 김"),

        ce(.elementary, "동식물의 한살이", ["완전 탈바꿈", "완전 변태"], "곤충이 알 → 애벌레 → 번데기 → 어른벌레의 단계를 거쳐 자라는 한살이예요. 번데기 시기에 몸의 생김새가 크게 바뀌어서 애벌레와 어른벌레의 모습이 많이 달라요.\n예: 배추흰나비, 벌, 파리, 무당벌레, 사슴벌레"),
        ce(.elementary, "동식물의 한살이", ["불완전 탈바꿈", "불완전 변태"], "번데기 단계 없이 알 → 애벌레 → 어른벌레로 자라는 곤충의 한살이예요. 애벌레가 허물을 여러 번 벗으며 점점 어른벌레를 닮아 가요.\n예: 잠자리, 메뚜기, 매미, 사마귀, 귀뚜라미"),
        ce(.elementary, "동식물의 한살이", ["식물의 한살이", "한해살이와 여러해살이"], "씨가 싹 터서 자라고, 꽃이 피고, 열매를 맺어 다시 씨를 만드는 과정이에요. 한 해 안에 한살이를 마치고 죽는 식물을 한해살이 식물, 여러 해 동안 살면서 꽃과 열매 맺기를 반복하는 식물을 여러해살이 식물이라고 해요.\n예: 한해살이 - 강낭콩, 벼, 옥수수 / 여러해살이 - 사과나무, 감나무, 개나리"),
        ce(.elementary, "동식물의 한살이", ["씨가 싹 트는 조건", "발아 조건"], "씨가 싹 트려면 알맞은 양의 물과 알맞은 온도가 필요해요. 씨는 처음에 씨 속의 양분을 쓰기 때문에 싹이 틀 때는 햇빛이 꼭 필요하지 않지만, 싹이 튼 뒤 잘 자라려면 햇빛이 필요해요.\n예: 젖은 솜 위의 강낭콩은 싹이 트지만, 마른 솜 위의 강낭콩은 싹이 트지 않아요."),
        ce(.elementary, "동식물의 한살이", ["꽃의 구조", "꽃가루받이"], "꽃은 보통 암술, 수술, 꽃잎, 꽃받침으로 이루어져요. 수술에서 만든 꽃가루가 암술로 옮겨지는 것을 꽃가루받이(수분)라고 하고, 꽃가루받이가 된 뒤 암술 아래쪽이 자라 씨와 열매가 돼요.\n예: 벌과 나비는 꿀을 먹으며 꽃가루를 옮기고, 벼와 옥수수는 바람이 꽃가루를 옮겨요."),

        ce(.elementary, "지구와 달의 운동", ["지구의 자전", "자전"], "지구가 자전축을 중심으로 서쪽에서 동쪽으로 하루에 한 바퀴씩 도는 운동이에요. 자전 때문에 낮과 밤이 번갈아 생기고, 태양과 달, 별이 동쪽에서 떠서 서쪽으로 지는 것처럼 보여요.\n예: 우리나라가 태양 쪽을 향하면 낮, 반대쪽을 향하면 밤이에요."),
        ce(.elementary, "지구와 달의 운동", ["지구의 공전", "공전"], "지구가 태양을 중심으로 1년에 한 바퀴씩 서쪽에서 동쪽으로 도는 운동이에요. 공전하면서 지구의 위치가 바뀌기 때문에 계절마다 밤하늘에서 보이는 별자리가 달라져요.\n예: 여름철에는 백조자리·거문고자리, 겨울철에는 오리온자리·큰개자리가 잘 보여요."),
        ce(.elementary, "지구와 달의 운동", ["달의 위상 변화", "달의 모양 변화"], "달은 스스로 빛을 내지 못하고 햇빛을 반사해서 밝게 보여요. 달이 지구 둘레를 공전하면서 우리 눈에 보이는 밝은 부분의 모양이 약 30일(약 29.5일)을 주기로 바뀌어요.\n예: 초승달(음력 2~3일) → 상현달(7~8일) → 보름달(15일) → 하현달(22~23일) → 그믐달(27~28일)"),
        ce(.elementary, "지구와 달의 운동", ["태양계 행성", "태양계 가족"], "태양계는 태양과 태양 주위를 도는 천체들로 이루어져 있어요. 행성은 태양에서 가까운 순서로 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성의 8개예요. 가장 큰 행성은 목성, 가장 작은 행성은 수성이에요.\n예: 달은 지구 주위를 도는 위성이고, 토성은 크고 뚜렷한 고리로 유명해요."),
        ce(.elementary, "지구와 달의 운동", ["별자리", "북극성 찾기"], "별자리는 밤하늘의 별들을 몇 개씩 묶어 동물이나 물건, 신화 속 인물의 이름을 붙인 것이에요. 북쪽 하늘의 북두칠성이나 카시오페이아자리를 이용하면 북극성을 찾을 수 있고, 북극성이 있는 쪽이 북쪽이에요.\n예: 북두칠성 국자 끝의 두 별을 이은 거리의 약 5배만큼 떨어진 곳에 북극성이 있어요."),

        ce(.elementary, "날씨와 우리 생활", ["습도", "건습구 습도계"], "공기 중에 수증기가 포함된 정도를 습도라고 해요. 건습구 습도계로 건구 온도와 습구 온도를 재고, 두 온도의 차이를 습도표에서 찾아 습도를 알아내요.\n예: 습도가 높으면 빨래가 잘 마르지 않고 곰팡이가 생기기 쉬우며, 습도가 낮으면 피부가 건조해지고 산불이 나기 쉬워요."),
        ce(.elementary, "날씨와 우리 생활", ["이슬·안개·구름", "이슬과 안개"], "이슬, 안개, 구름은 모두 공기 중의 수증기가 응결해서 생겨요. 이슬은 차가워진 물체 표면에 물방울로 맺힌 것, 안개는 지표면 가까운 공기 속에서 응결한 물방울이 떠 있는 것, 구름은 높은 하늘에서 응결한 물방울이나 얼음 알갱이가 떠 있는 것이에요. 구름 속 물방울이 커지고 무거워지면 비나 눈이 되어 내려요.\n예: 맑고 바람 없는 새벽에 이슬과 안개가 잘 생겨요."),
        ce(.elementary, "날씨와 우리 생활", ["고기압과 저기압", "기압"], "공기의 무게 때문에 생기는 누르는 힘을 기압이라고 해요. 같은 부피일 때 차가운 공기는 무거워서 기압이 높고(고기압), 따뜻한 공기는 가벼워서 기압이 낮아요(저기압). 바람은 기압이 높은 곳에서 낮은 곳으로 불어요.\n예: 고기압이 머무는 날은 대체로 맑고, 저기압이 다가오면 흐리거나 비가 와요."),
        ce(.elementary, "날씨와 우리 생활", ["해풍과 육풍", "바닷가의 바람"], "낮에는 육지가 바다보다 빨리 데워져 육지 위가 저기압이 되므로 바다에서 육지로 해풍이 불어요. 밤에는 육지가 바다보다 빨리 식어 바다 위가 저기압이 되므로 육지에서 바다로 육풍이 불어요.\n예: 여름 한낮 해수욕장에서는 바다 쪽에서 시원한 바람이 불어와요."),

        ce(.elementary, "자석의 이용", ["자석의 극", "N극과 S극"], "자석에서 철로 된 물체를 끌어당기는 힘이 가장 센 양쪽 끝부분을 자석의 극이라고 해요. 자석에는 항상 N극과 S극이 함께 있고, 같은 극끼리는 서로 밀어내고 다른 극끼리는 서로 끌어당겨요.\n예: 막대자석을 반으로 잘라도 각 조각에 다시 N극과 S극이 생겨요."),
        ce(.elementary, "자석의 이용", ["나침반", "나침반의 원리"], "나침반의 바늘은 자유롭게 회전하는 작은 자석이에요. 지구가 커다란 자석처럼 작용하기 때문에 바늘의 N극은 항상 북쪽을, S극은 남쪽을 가리켜요.\n예: 나침반 가까이에 막대자석을 가져가면 바늘이 북쪽이 아닌 자석 쪽으로 돌아가요."),
        ce(.elementary, "자석의 이용", ["자석에 붙는 물체", "철로 된 물체"], "자석은 철로 된 물체를 끌어당겨요. 금속이라도 알루미늄이나 구리처럼 자석에 붙지 않는 것이 있고, 플라스틱·나무·유리·고무도 자석에 붙지 않아요. 자석의 힘은 종이나 얇은 플라스틱을 사이에 두어도 작용해요.\n예: 철 클립과 철 못은 붙지만, 알루미늄 캔과 10원짜리 동전은 붙지 않아요."),

        ce(.elementary, "빛과 렌즈", ["그림자", "빛의 직진"], "빛은 곧게 나아가는 성질(직진)이 있어서, 빛이 물체에 가로막히면 물체 뒤쪽에 그림자가 생겨요. 불투명한 물체는 진한 그림자, 투명한 물체는 연한 그림자가 생겨요. 물체를 손전등에 가까이 가져가면 그림자가 커지고, 멀리하면 작아져요.\n예: 그림자 연극에서 인형을 빛 쪽으로 옮기면 그림자가 커져요."),
        ce(.elementary, "빛과 렌즈", ["빛의 반사", "거울"], "빛이 나아가다가 물체에 부딪쳐 방향을 바꾸어 되돌아 나오는 현상을 빛의 반사라고 해요. 거울은 빛을 잘 반사하는데, 평면거울에 비친 모습은 실제와 크기가 같고 좌우가 바뀌어 보여요.\n예: 구급차 앞쪽에 좌우가 바뀐 글자를 써 두면, 앞차 운전자가 뒷거울로 볼 때 바르게 읽혀요."),
        ce(.elementary, "빛과 렌즈", ["빛의 굴절", "굴절"], "빛이 공기에서 물이나 유리로 비스듬히 들어갈 때, 두 물질의 경계에서 꺾여 나아가는 현상이에요. 경계에 수직으로 들어가면 꺾이지 않고 그대로 나아가요.\n예: 물이 담긴 컵에 젓가락을 넣으면 꺾여 보이고, 물속에 있는 다리가 실제보다 짧아 보여요."),
        ce(.elementary, "빛과 렌즈", ["볼록 렌즈", "convex lens"], "가운데 부분이 가장자리보다 두꺼운 렌즈예요. 볼록 렌즈를 통과한 빛은 굴절되어 한 점으로 모이기 때문에, 햇빛을 모으면 그 부분이 밝고 뜨거워져요. 가까운 물체를 보면 실제보다 크게 보이고, 멀리 있는 물체는 거꾸로 보이기도 해요.\n예: 돋보기, 현미경, 망원경, 사진기 렌즈"),
        ce(.elementary, "빛과 렌즈", ["프리즘", "햇빛의 색"], "프리즘은 유리나 플라스틱으로 만든 삼각기둥 모양의 투명한 도구예요. 햇빛이 프리즘을 통과하면 굴절되면서 빨강부터 보라까지 여러 가지 색의 빛으로 나뉘어요. 이것으로 햇빛이 여러 색의 빛이 섞인 것임을 알 수 있어요.\n예: 비가 갠 뒤 공기 중의 물방울이 프리즘처럼 햇빛을 나누어 무지개가 생겨요."),

        ce(.elementary, "전기의 이용", ["전기 회로", "electric circuit"], "전지, 전선, 전구, 스위치 같은 전기 부품을 연결해 전기가 흐르도록 한 것을 전기 회로라고 해요. 전구의 두 연결 부분이 전지의 (+)극과 (−)극에 각각 끊기지 않게 이어져야 불이 켜져요.\n예: 스위치를 열면 회로가 끊어져 전구가 꺼지고, 닫으면 다시 켜져요."),
        ce(.elementary, "전기의 이용", ["전구의 직렬연결", "직렬연결"], "전구 여러 개를 한 줄로 이어서 연결하는 방법이에요. 전구 하나를 빼면 회로가 끊어져 나머지 전구도 모두 꺼져요. 같은 전지에 전구를 더 많이 직렬로 연결할수록 각 전구의 밝기가 어두워져요.\n예: 전구 두 개를 직렬로 연결하면 한 개만 연결했을 때보다 어두워요."),
        ce(.elementary, "전기의 이용", ["전구의 병렬연결", "병렬연결"], "전구를 여러 갈래로 나누어 각각 전지에 연결하는 방법이에요. 전구 하나를 빼도 나머지 전구는 계속 켜져 있고, 각 전구의 밝기는 전구 하나만 연결했을 때와 비슷하게 밝아요. 대신 전지가 더 빨리 닳아요.\n예: 집 안의 전등과 콘센트는 병렬로 연결되어 있어서 하나를 꺼도 다른 것은 켜져 있어요."),
        ce(.elementary, "전기의 이용", ["도체와 부도체", "전기가 통하는 물질"], "철·구리·알루미늄 같은 금속처럼 전기가 잘 통하는 물질을 도체라고 하고, 플라스틱·고무·유리·나무처럼 전기가 잘 통하지 않는 물질을 부도체(절연체)라고 해요.\n예: 전선은 안쪽의 구리선으로 전기가 흐르고, 바깥을 플라스틱으로 감싸 감전을 막아요."),
        ce(.elementary, "전기의 이용", ["전자석", "electromagnet"], "철심에 코일(에나멜선)을 감고 전류를 흘려 주면 자석이 되는 것이에요. 전류가 흐를 때만 자석이 되고, 전지를 직렬로 더 연결하거나 코일을 더 많이 감으면 세기가 세져요. 전류의 방향을 바꾸면 N극과 S극도 바뀌어요.\n예: 고철을 들어 올리는 기중기, 스피커, 전동기(선풍기·세탁기), 자기 부상 열차"),

        ce(.elementary, "용해와 용액", ["용해", "용질·용매·용액"], "어떤 물질이 다른 물질에 녹아 고르게 섞이는 현상을 용해라고 해요. 녹는 물질을 용질, 녹이는 물질을 용매, 용질이 용매에 녹아 고르게 섞인 물질을 용액이라고 해요. 용액은 오래 두어도 가라앉거나 뜨는 것이 없어요.\n예: 소금(용질)이 물(용매)에 녹아 소금물(용액)이 돼요."),
        ce(.elementary, "용해와 용액", ["용해 전후의 무게", "녹은 물질의 무게"], "물질이 물에 녹으면 눈에 보이지 않을 뿐 없어지는 것이 아니라 아주 작게 나뉘어 물속에 고르게 섞여 있어요. 그래서 용액의 무게는 녹이기 전 물의 무게와 용질의 무게를 더한 것과 같아요.\n예: 물 100g에 설탕 10g을 완전히 녹이면 설탕물의 무게는 110g이에요."),
        ce(.elementary, "용해와 용액", ["물의 온도와 용해되는 양", "용해되는 양"], "같은 온도, 같은 양의 물에 녹을 수 있는 양은 용질의 종류마다 달라요. 또 대부분의 고체 용질은 물의 온도가 높을수록 더 많이 녹아요. 따뜻한 물에 많이 녹인 용액을 식히면 다 녹아 있지 못한 용질이 알갱이로 다시 나와요.\n예: 따뜻한 물에 백반을 녹인 뒤 얼음물에 넣어 식히면 백반 알갱이가 생겨요."),
        ce(.elementary, "용해와 용액", ["용액의 진하기", "진하기 비교"], "같은 양의 용매에 녹아 있는 용질의 양이 많을수록 용액이 진해요. 투명한 용액의 진하기는 맛을 보지 않고도 물체가 뜨는 정도로 비교할 수 있어요. 진한 용액일수록 물체가 더 높이 떠요.\n예: 진한 설탕물에서는 방울토마토가 떠오르고, 연한 설탕물에서는 가라앉아요."),

        ce(.elementary, "산과 염기", ["지시약", "리트머스 종이"], "어떤 용액을 만났을 때 그 용액의 성질에 따라 색깔이 달라지는 물질을 지시약이라고 해요. 리트머스 종이, 페놀프탈레인 용액, BTB 용액, 붉은 양배추 지시약 등이 있어요.\n예: 푸른 리트머스 종이는 산성 용액에서 붉게, 붉은 리트머스 종이는 염기성 용액에서 푸르게 변해요."),
        ce(.elementary, "산과 염기", ["산성 용액", "산성"], "푸른 리트머스 종이를 붉게 변하게 하고, 페놀프탈레인 용액의 색깔은 변하게 하지 않는 용액이에요. 붉은 양배추 지시약은 붉은색 계열로 변해요. 대리석 조각이나 달걀 껍데기를 넣으면 기포가 생기며 녹아요.\n예: 식초, 레몬즙, 탄산수, 묽은 염산"),
        ce(.elementary, "산과 염기", ["염기성 용액", "염기성"], "붉은 리트머스 종이를 푸르게, 페놀프탈레인 용액을 붉게 변하게 하는 용액이에요. 붉은 양배추 지시약은 푸른색이나 노란색 계열로 변해요. 삶은 달걀흰자나 두부를 넣으면 흐물흐물하게 녹아요.\n예: 비눗물, 유리 세정제, 석회수, 묽은 수산화 나트륨 용액"),
        ce(.elementary, "산과 염기", ["산과 염기의 섞임", "산성과 염기성 용액 섞기"], "산성 용액에 염기성 용액을 조금씩 넣으면 산성이 점점 약해지다가 염기성으로 바뀌어요. 반대로 염기성 용액에 산성 용액을 넣으면 염기성이 약해져요. 우리 생활에서는 이 성질을 여러 곳에 이용해요.\n예: 속이 쓰릴 때 염기성인 제산제를 먹고, 산성화된 토양에 염기성인 석회 가루를 뿌려요."),

        ce(.elementary, "우리 몸의 구조와 기능", ["뼈와 근육", "운동 기관"], "뼈는 몸의 형태를 만들고 몸을 지탱하며, 뇌·심장·폐 같은 몸속 기관을 보호해요. 뼈에 연결된 근육이 줄어들거나 늘어나면서 뼈를 움직여 몸이 움직여요. 뼈와 근육처럼 몸을 움직이게 하는 기관을 운동 기관이라고 해요.\n예: 팔을 구부리면 팔 안쪽 근육이 줄어들면서 아래팔뼈를 끌어올려요."),
        ce(.elementary, "우리 몸의 구조와 기능", ["소화 기관", "음식물이 지나가는 길"], "음식물을 잘게 쪼개 몸에 흡수될 수 있도록 하는 기관이에요. 음식물은 입 → 식도 → 위 → 작은창자 → 큰창자 → 항문 순서로 이동하고, 간·쓸개·이자는 소화를 도와요.\n예: 작은창자에서는 음식물의 영양소가, 큰창자에서는 주로 수분이 흡수돼요."),
        ce(.elementary, "우리 몸의 구조와 기능", ["호흡 기관", "숨쉬기"], "숨을 쉬며 공기를 들이마시고 내보내는 데 관여하는 기관이에요. 들이마신 공기는 코 → 기관 → 기관지 → 폐로 들어가고, 폐에서 몸에 필요한 산소를 받아들이고 몸에서 생긴 이산화 탄소를 내보내요.\n예: 숨을 들이마시면 가슴이 부풀고, 내쉬면 가슴이 작아져요."),
        ce(.elementary, "우리 몸의 구조와 기능", ["순환 기관", "심장과 혈관"], "혈액을 온몸으로 순환시키는 기관으로, 심장과 혈관이 있어요. 심장이 펌프 작용으로 혈액을 내보내면 혈액은 혈관을 따라 온몸을 돌면서 영양소와 산소를 전달하고 다시 심장으로 돌아와요.\n예: 운동을 하면 심장이 더 빨리 뛰어 맥박 수가 늘어나요."),
        ce(.elementary, "우리 몸의 구조와 기능", ["배설 기관", "콩팥과 방광"], "혈액 속의 노폐물을 몸 밖으로 내보내는 기관이에요. 콩팥이 혈액에서 노폐물을 걸러 오줌을 만들고, 오줌은 오줌관을 지나 방광에 모였다가 요도를 통해 몸 밖으로 나가요.\n예: 물을 많이 마시면 오줌의 양이 늘어나요."),
        ce(.elementary, "우리 몸의 구조와 기능", ["감각 기관", "자극이 전달되는 과정"], "눈·귀·코·혀·피부처럼 주변의 자극을 받아들이는 기관을 감각 기관이라고 해요. 감각 기관이 받아들인 자극은 신경계를 거쳐 뇌로 전달되고, 뇌가 판단하여 내린 명령이 다시 신경계를 통해 운동 기관으로 전달되어 행동하게 돼요.\n예: 날아오는 공을 눈으로 보고(자극) 뇌가 판단해 손으로 잡아요(반응)."),

        ce(.elementary, "계절의 변화", ["태양의 남중 고도", "태양 고도"], "태양 고도는 태양이 지평선과 이루는 각이고, 태양이 정남쪽에 와서 하루 중 가장 높을 때의 고도를 남중 고도라고 해요. 우리나라에서는 남중 고도가 여름에 가장 높고 겨울에 가장 낮아요. 남중 고도가 높을수록 그림자가 짧고 낮의 길이가 길며 기온이 높아요.\n예: 하루 중 태양 고도는 낮 12시 30분 무렵 가장 높고, 기온은 오후 2시 30분 무렵 가장 높아요."),
        ce(.elementary, "계절의 변화", ["계절이 생기는 까닭", "자전축의 기울기"], "지구의 자전축이 공전 궤도면에 수직인 방향에서 약 23.5° 기울어진 채로 태양 주위를 공전하기 때문에 계절이 생겨요. 공전 위치에 따라 태양의 남중 고도가 달라지고, 남중 고도가 높으면 같은 면적이 받는 태양 에너지가 많아져 기온이 높아져요.\n예: 자전축이 기울어지지 않았다면 남중 고도가 1년 내내 같아서 계절 변화가 생기지 않아요."),

        ce(.elementary, "생물과 환경", ["생태계", "ecosystem"], "어떤 장소에서 서로 영향을 주고받는 생물 요소와 비생물 요소를 모두 합한 것을 생태계라고 해요. 비생물 요소에는 햇빛, 물, 온도, 공기, 흙 등이 있어요.\n예: 숲, 연못, 갯벌, 학교 화단도 각각 하나의 생태계예요."),
        ce(.elementary, "생물과 환경", ["생산자·소비자·분해자", "생물 요소의 분류"], "생물 요소는 양분을 얻는 방법에 따라 나눌 수 있어요. 생산자는 햇빛을 이용해 스스로 양분을 만들고(식물), 소비자는 다른 생물을 먹어 양분을 얻으며(동물), 분해자는 죽은 생물이나 배출물을 분해해 양분을 얻어요(곰팡이, 세균, 버섯).\n예: 벼(생산자), 메뚜기·개구리(소비자), 곰팡이(분해자)"),
        ce(.elementary, "생물과 환경", ["먹이 사슬", "먹이 그물"], "생물들 사이의 먹고 먹히는 관계가 사슬처럼 연결된 것을 먹이 사슬, 여러 개의 먹이 사슬이 그물처럼 얽힌 것을 먹이 그물이라고 해요. 먹이 그물에서는 어느 한 생물이 사라져도 다른 먹이를 먹을 수 있어서 생태계가 잘 유지돼요.\n예: 벼 → 메뚜기 → 개구리 → 뱀 → 매"),
        ce(.elementary, "생물과 환경", ["생태계 평형", "생태계 균형"], "어떤 지역에 사는 생물의 종류와 수가 균형을 이루며 안정된 상태를 유지하는 것이에요. 홍수·산불 같은 자연재해나 도로 건설, 무분별한 사냥 같은 사람의 활동으로 깨질 수 있고, 회복하는 데 오랜 시간이 걸려요.\n예: 미국 옐로스톤 국립공원에서 늑대가 사라지자 사슴이 늘어 풀과 나무가 줄었고, 늑대를 다시 데려온 뒤 회복되었어요."),
        ce(.elementary, "생물과 환경", ["환경 적응", "적응"], "생물이 오랜 기간에 걸쳐 사는 곳의 환경에 알맞은 생김새와 생활 방식을 갖게 되는 것을 적응이라고 해요.\n예: 사막여우는 큰 귀로 몸의 열을 내보내고, 북극여우는 작은 귀와 두꺼운 털로 열을 지켜요. 선인장은 잎이 가시로 변해 물이 빠져나가는 것을 줄여요."),

        // MARK: - 중학교

        ce(.middle, "여러 가지 힘", ["중력", "무게와 질량"], "지구가 물체를 지구 중심 방향으로 끌어당기는 힘이에요. 물체의 무게는 물체에 작용하는 중력의 크기로 단위는 N(뉴턴)이고, 질량은 장소에 따라 변하지 않는 물질의 고유한 양으로 단위는 kg이에요. 지구에서 질량 1kg인 물체의 무게는 약 9.8N이에요.\n예: 달의 중력은 지구의 약 1/6이라서 지구에서 무게가 60N인 물체는 달에서 약 10N이지만, 질량은 그대로예요."),
        ce(.middle, "여러 가지 힘", ["부력", "buoyancy"], "액체나 기체가 그 속에 있는 물체를 위쪽으로 밀어 올리는 힘이에요. 부력의 크기는 물체가 잠긴 부피만큼의 액체(유체)의 무게와 같아요(아르키메데스 원리). 그래서 물체가 많이 잠길수록 부력이 커져요.\n예: 공기 중에서 10N인 추를 물에 완전히 담갔더니 용수철저울이 7N을 가리키면 부력은 3N이에요."),
        ce(.middle, "운동과 에너지", ["속력", "speed"], "물체가 단위 시간 동안 이동한 거리예요. 속력 = 이동 거리 ÷ 걸린 시간이고, 단위는 m/s, km/h 등을 써요. 속력이 일정한 운동을 등속 운동이라고 하는데, 이때 시간-이동 거리 그래프는 원점을 지나는 직선이고 기울기가 속력이에요.\n예: 100m를 20초 동안 달렸다면 평균 속력은 5m/s예요. 36km/h는 10m/s와 같아요."),
        ce(.middle, "운동과 에너지", ["자유 낙하 운동", "free fall"], "공기 저항 없이 중력만 받아 떨어지는 운동이에요. 운동 방향으로 일정한 크기의 중력을 받으므로 속력이 1초마다 약 9.8m/s씩 일정하게 빨라져요. 공기 저항이 없다면 질량이 다른 물체도 같은 높이에서 동시에 떨어져요.\n예: 진공 상태의 관 속에서 깃털과 쇠구슬을 떨어뜨리면 동시에 바닥에 닿아요."),
        ce(.middle, "에너지 전환과 보존", ["역학적 에너지", "위치 에너지와 운동 에너지", "역학적 에너지 보존"], "과학에서 일은 힘 × 힘의 방향으로 이동한 거리이고 단위는 J(줄)이에요. 중력에 의한 위치 에너지는 9.8 × 질량(kg) × 높이(m), 운동 에너지는 1/2 × 질량 × 속력²이고, 이 둘의 합이 역학적 에너지예요. 공기 저항과 마찰이 없으면 역학적 에너지는 항상 일정하게 보존돼요.\n예: 롤러코스터가 내려올 때는 위치 에너지가 운동 에너지로 바뀌어 빨라져요."),

        ce(.middle, "빛과 파동", ["빛의 삼원색", "빛의 합성"], "빨간색, 초록색, 파란색 빛을 빛의 삼원색이라고 해요. 세 가지 빛을 적절히 합성하면 여러 가지 색을 만들 수 있고, 모두 합치면 흰색이 돼요. 빨강 + 초록 = 노랑, 초록 + 파랑 = 청록(사이안), 빨강 + 파랑 = 자홍(마젠타)이에요.\n예: 텔레비전과 스마트폰 화면은 빨강·초록·파랑의 작은 점(화소)으로 모든 색을 표현해요."),
        ce(.middle, "빛과 파동", ["렌즈에 의한 상", "볼록 렌즈와 오목 렌즈"], "볼록 렌즈는 빛을 모으는 렌즈로, 물체가 초점 밖에 있으면 거꾸로 선 실상이, 초점 안에 있으면 크고 바로 선 허상이 생겨요. 오목 렌즈는 빛을 퍼뜨리는 렌즈로, 항상 물체보다 작고 바로 선 허상이 생겨요. 빛이 반사할 때는 입사각과 반사각이 항상 같아요(반사 법칙).\n예: 근시 교정 안경은 오목 렌즈, 원시 교정 안경과 돋보기는 볼록 렌즈예요."),
        ce(.middle, "빛과 파동", ["파동", "횡파와 종파"], "한 곳에서 생긴 진동이 주위로 퍼져 나가는 현상이에요. 매질은 제자리에서 진동만 하고 에너지가 전달돼요. 진동 방향과 진행 방향이 수직이면 횡파(빛, 지진파의 S파), 나란하면 종파(소리, 지진파의 P파)예요. 마루와 마루 사이 거리를 파장, 진동 중심에서 마루까지 높이를 진폭, 1초 동안 진동한 횟수를 진동수(Hz)라고 해요.\n예: 물결파 위의 나뭇잎은 앞으로 가지 않고 위아래로만 움직여요."),
        ce(.middle, "빛과 파동", ["소리의 3요소", "소리의 크기·높낮이·맵시"], "소리의 크기는 진폭이 클수록 크고, 소리의 높낮이는 진동수가 클수록 높으며, 소리의 맵시(음색)는 파형에 따라 달라져요. 사람은 보통 진동수 약 20~20000Hz의 소리를 들을 수 있고, 이보다 높은 소리를 초음파라고 해요.\n예: 같은 높이의 음을 내도 피아노와 바이올린 소리가 다르게 들리는 것은 파형이 다르기 때문이에요."),

        ce(.middle, "전기와 자기", ["대전", "정전기"], "서로 다른 두 물체를 마찰하면 한 물체에서 다른 물체로 전자가 이동해요. 전자를 잃은 물체는 (+)전하, 전자를 얻은 물체는 (−)전하를 띠게 되는데, 이를 대전이라고 해요. 같은 종류의 전하는 서로 밀어내고 다른 종류의 전하는 서로 끌어당겨요.\n예: 플라스틱 빗으로 머리를 빗으면 머리카락이 빗에 달라붙고, 건조한 날 문고리를 잡으면 따끔해요."),
        ce(.middle, "전기와 자기", ["옴의 법칙", "전류·전압·저항"], "전류는 전하의 흐름(단위 A), 전압은 전류를 흐르게 하는 능력(단위 V), 저항은 전류의 흐름을 방해하는 정도(단위 Ω)예요. 전류의 세기는 전압에 비례하고 저항에 반비례해요. V = I × R. 저항을 직렬로 연결하면 전체 저항이 커지고, 병렬로 연결하면 작아져요.\n예: 저항이 10Ω인 니크롬선에 3V를 걸면 0.3A의 전류가 흘러요."),
        ce(.middle, "전기와 자기", ["전력", "전력량"], "전력은 1초 동안 전기 기구가 사용하는 전기 에너지로, 전력(W) = 전압(V) × 전류(A)예요. 전력량은 일정 시간 동안 사용한 전기 에너지로, 전력량(Wh) = 전력(W) × 사용 시간(h)이에요.\n예: 소비 전력이 1000W인 전기 주전자를 30분 사용하면 전력량은 500Wh, 즉 0.5kWh예요."),
        ce(.middle, "전기와 자기", ["전류의 자기 작용", "오른손 법칙"], "전류가 흐르는 도선 주위에는 자기장이 생겨요. 오른손 엄지손가락을 전류의 방향으로 하고 도선을 감아쥐면 네 손가락이 감기는 방향이 자기장의 방향이에요. 또 자기장 속에서 전류가 흐르는 도선은 힘을 받는데, 이 원리로 전동기가 회전해요.\n예: 전동기(모터)는 선풍기, 세탁기, 전기 자동차 등에 쓰여요."),

        ce(.middle, "열과 우리 생활", ["열의 이동", "전도·대류·복사"], "열은 온도가 높은 곳에서 낮은 곳으로 이동해요. 전도는 고체에서 입자의 운동이 이웃 입자로 차례로 전달되는 방식, 대류는 액체나 기체에서 입자가 직접 이동하며 열을 전달하는 방식, 복사는 물질의 도움 없이 열이 직접 전달되는 방식이에요. 결국 두 물체의 온도가 같아진 상태를 열평형이라고 해요.\n예: 냄비 손잡이가 뜨거워짐(전도), 에어컨은 위쪽에 설치(대류), 햇볕이 따뜻함(복사)"),
        ce(.middle, "열과 우리 생활", ["비열", "specific heat"], "어떤 물질 1kg의 온도를 1°C 높이는 데 필요한 열량이에요. 단위는 kcal/(kg·°C) 또는 J/(kg·°C)이고, 물의 비열은 약 1kcal/(kg·°C), 즉 약 4200J/(kg·°C)으로 매우 큰 편이에요. 열량 = 비열 × 질량 × 온도 변화예요. 비열이 클수록 온도가 잘 변하지 않아요.\n예: 바닷가 지역은 비열이 큰 바닷물 때문에 내륙보다 일교차가 작아요."),
        ce(.middle, "물질의 상태 변화", ["상태 변화", "융해·응고·기화·액화·승화"], "고체 → 액체는 융해, 액체 → 고체는 응고, 액체 → 기체는 기화, 기체 → 액체는 액화, 고체 ↔ 기체는 승화라고 해요. 상태가 변해도 입자의 종류와 수는 변하지 않아 질량은 일정하지만, 입자 배열이 달라져 부피는 변해요. 융해·기화·승화(고체 → 기체) 때는 열을 흡수하고, 응고·액화·승화(기체 → 고체) 때는 열을 방출해요.\n예: 드라이아이스가 기체로 바뀌는 것은 승화예요."),
        ce(.middle, "기체의 성질", ["보일 법칙", "Boyle's law"], "온도가 일정할 때 일정량의 기체의 부피는 압력에 반비례해요. 즉 압력 × 부피 = 일정이에요. 압력이 커지면 기체 입자 사이의 거리가 가까워져 부피가 줄어들어요.\n예: 1기압에서 6L인 기체에 3기압을 가하면 부피는 2L가 돼요. 높은 산에 올라가면 과자 봉지가 부풀어요."),
        ce(.middle, "기체의 성질", ["샤를 법칙", "Charles's law"], "압력이 일정할 때 일정량의 기체의 부피는 온도가 1°C 높아질 때마다 0°C일 때 부피의 1/273씩 증가해요. 온도가 높아지면 기체 입자의 운동이 활발해져 부피가 커져요.\n예: 찌그러진 탁구공을 뜨거운 물에 넣으면 펴지고, 열기구는 풍선 속 공기를 가열해 떠올라요."),

        ce(.middle, "물질의 구성", ["원소", "element"], "더 이상 다른 물질로 분해되지 않는 물질의 기본 성분이에요. 현재까지 118가지가 알려져 있어요. 일부 금속 원소는 불꽃 반응 색이나 선 스펙트럼으로 구별할 수 있어요.\n예: 수소(H), 산소(O), 철(Fe), 구리(Cu). 불꽃 반응 색은 나트륨 노란색, 리튬 빨간색, 칼륨 보라색, 구리 청록색이에요."),
        ce(.middle, "물질의 구성", ["원자", "atom"], "물질을 이루는 기본 입자예요. 원자의 중심에는 (+)전하를 띠는 원자핵이 있고, 그 주위를 (−)전하를 띠는 전자가 움직이고 있어요. 원자핵의 (+)전하량과 전자 전체의 (−)전하량이 같아서 원자는 전기적으로 중성이에요.\n예: 산소 원자는 원자핵의 전하가 +8이고, 전자가 8개 있어요."),
        ce(.middle, "물질의 구성", ["분자", "molecule"], "독립된 입자로 존재하여 물질의 성질을 나타내는 가장 작은 입자로, 원자가 결합해서 만들어져요. 분자는 원소 기호와 숫자를 이용한 화학식으로 나타내요.\n예: 물 분자(H₂O)는 수소 원자 2개와 산소 원자 1개, 이산화 탄소 분자(CO₂)는 탄소 원자 1개와 산소 원자 2개, 암모니아 분자(NH₃)는 질소 원자 1개와 수소 원자 3개로 이루어져요."),
        ce(.middle, "물질의 구성", ["이온", "ion"], "원자가 전자를 잃거나 얻어서 전하를 띠게 된 입자예요. 전자를 잃으면 양이온, 전자를 얻으면 음이온이 돼요. 이온이 녹아 있는 수용액에 전압을 걸면 양이온은 (−)극, 음이온은 (+)극으로 이동해서 전류가 흘러요.\n예: Na → Na⁺ + e⁻ (나트륨 이온), Cl + e⁻ → Cl⁻ (염화 이온), Mg → Mg²⁺ + 2e⁻"),
        ce(.middle, "물질의 구성", ["앙금 생성 반응", "precipitation reaction"], "특정한 양이온과 음이온이 만나 물에 녹지 않는 앙금을 만드는 반응이에요. 앙금 생성 반응을 이용하면 수용액 속에 어떤 이온이 들어 있는지 확인할 수 있어요.\n예: Ag⁺ + Cl⁻ → AgCl(흰색), Ca²⁺ + CO₃²⁻ → CaCO₃(흰색), Ba²⁺ + SO₄²⁻ → BaSO₄(흰색), Pb²⁺ + 2I⁻ → PbI₂(노란색)"),

        ce(.middle, "화학 반응의 규칙과 에너지 변화", ["화학 변화", "물리 변화와 화학 변화"], "물리 변화는 물질의 모양이나 상태만 변하고 고유한 성질은 그대로인 변화이고, 화학 변화는 원자의 배열이 달라져 처음과 성질이 다른 새로운 물질이 생기는 변화예요. 화학 변화는 화학 반응식으로 나타내며, 반응 전후 원자의 종류와 개수가 같도록 계수를 맞춰요.\n예: 종이를 찢는 것은 물리 변화, 종이를 태우는 것은 화학 변화예요. 2H₂ + O₂ → 2H₂O"),
        ce(.middle, "화학 반응의 규칙과 에너지 변화", ["질량 보존 법칙", "law of conservation of mass"], "화학 반응이 일어날 때 반응 전 물질의 총질량과 반응 후 물질의 총질량은 같아요(라부아지에). 원자가 새로 생기거나 없어지지 않고 배열만 바뀌기 때문이에요. 열린 용기에서 기체가 빠져나가거나 들어오면 질량이 변하는 것처럼 보일 뿐이에요.\n예: 강철 솜을 태우면 산소와 결합해 질량이 늘고, 나무를 태우면 기체가 날아가 재의 질량이 줄어요."),
        ce(.middle, "화학 반응의 규칙과 에너지 변화", ["일정 성분비 법칙", "law of definite proportions"], "한 화합물을 이루는 성분 원소들 사이에는 항상 일정한 질량비가 성립해요(프루스트). 화합물은 원자가 일정한 개수비로 결합해 만들어지기 때문이에요. 혼합물에는 이 법칙이 성립하지 않아요.\n예: 물은 수소와 산소의 질량비가 1 : 8, 산화 구리(Ⅱ)는 구리와 산소의 질량비가 4 : 1이에요. 구리 8g이 모두 반응하면 산화 구리(Ⅱ) 10g이 생겨요."),
        ce(.middle, "화학 반응의 규칙과 에너지 변화", ["발열 반응과 흡열 반응", "발열 반응", "흡열 반응"], "화학 반응이 일어날 때 에너지를 방출해 주위의 온도가 높아지는 반응을 발열 반응, 에너지를 흡수해 주위의 온도가 낮아지는 반응을 흡열 반응이라고 해요.\n예: 발열 반응 - 연소, 철 가루가 산화되는 손난로, 산과 염기의 중화 반응 / 흡열 반응 - 질산 암모늄과 물을 이용한 냉찜질 팩, 광합성, 베이킹 소다의 열분해"),

        ce(.middle, "생물의 구성과 다양성", ["세포", "cell"], "생물체를 이루는 구조적·기능적 기본 단위예요. 동물 세포와 식물 세포에는 공통적으로 핵, 세포막, 세포질, 미토콘드리아가 있고, 식물 세포에는 세포벽과 엽록체가 더 있어요. 동물은 세포 → 조직 → 기관 → 기관계 → 개체, 식물은 세포 → 조직 → 조직계 → 기관 → 개체의 단계로 구성돼요.\n예: 양파 표피 세포에서는 세포벽을, 입안 상피 세포에서는 둥근 세포 모양을 관찰할 수 있어요."),
        ce(.middle, "생물의 구성과 다양성", ["생물 다양성", "biodiversity", "변이"], "일정한 지역에 살고 있는 생물의 다양한 정도로, 유전적 다양성·종 다양성·생태계 다양성을 모두 포함해요. 같은 종이라도 개체마다 형질이 조금씩 다른 것을 변이라고 하는데, 변이가 다양할수록 환경 변화에 적응해 살아남을 가능성이 커요.\n예: 아시아무당벌레의 등 무늬가 개체마다 다른 것은 유전적 다양성의 예예요."),
        ce(.middle, "생물의 구성과 다양성", ["생물 분류", "분류 단계"], "생물을 공통적인 특징에 따라 무리 지어 나누는 것이에요. 분류 단계는 종 < 속 < 과 < 목 < 강 < 문 < 계이고, 종은 자연 상태에서 짝짓기하여 생식 능력이 있는 자손을 낳을 수 있는 무리예요. 생물은 원핵생물계, 원생생물계, 균계, 식물계, 동물계의 5계로 나눌 수 있어요.\n예: 말과 당나귀 사이에서 태어난 노새는 생식 능력이 없으므로 말과 당나귀는 서로 다른 종이에요."),

        ce(.middle, "동물과 에너지", ["영양소", "3대 영양소"], "탄수화물(1g당 약 4kcal), 단백질(약 4kcal), 지방(약 9kcal)은 에너지원으로 쓰이는 3대 영양소이고, 물·무기염류·바이타민은 에너지를 내지 않지만 몸의 기능을 조절해요.\n예: 녹말은 아이오딘 반응(청람색), 포도당은 베네딕트 반응(가열 시 황적색), 단백질은 뷰렛 반응(보라색), 지방은 수단Ⅲ 반응(선홍색)으로 검출해요."),
        ce(.middle, "동물과 에너지", ["소화 효소", "소화 과정"], "소화 효소는 영양소를 작은 단위로 분해해요. 입의 침 속 아밀레이스는 녹말을 엿당으로, 위의 펩신은 단백질을 분해하고(염산이 도움), 이자액의 아밀레이스·트립신·라이페이스와 소장의 소화 효소가 최종 분해를 마쳐요. 쓸개즙은 효소가 없지만 지방을 작은 알갱이로 만들어 소화를 도와요.\n예: 최종 산물은 포도당, 아미노산, 지방산과 모노글리세리드이며 소장의 융털에서 흡수돼요."),
        ce(.middle, "동물과 에너지", ["혈액 순환", "온몸 순환과 폐순환"], "온몸 순환은 좌심실 → 대동맥 → 온몸의 모세 혈관 → 대정맥 → 우심방 순서로, 온몸의 세포에 산소와 영양소를 전달해요. 폐순환은 우심실 → 폐동맥 → 폐의 모세 혈관 → 폐정맥 → 좌심방 순서로, 폐에서 이산화 탄소를 내보내고 산소를 받아요. 혈액의 적혈구는 산소 운반, 백혈구는 식균 작용, 혈소판은 혈액 응고를 맡아요.\n예: 폐정맥에는 산소가 많은 동맥혈이 흘러요."),
        ce(.middle, "동물과 에너지", ["호흡 운동", "들숨과 날숨"], "폐는 근육이 없어서 스스로 움직이지 못하고, 갈비뼈와 가로막의 움직임으로 호흡해요. 들숨 때는 갈비뼈가 올라가고 가로막이 내려가 흉강의 부피가 커지고 압력이 낮아져 공기가 들어와요. 날숨 때는 그 반대예요. 폐포와 모세 혈관 사이에서는 농도 차에 의한 확산으로 기체가 교환돼요.\n예: 고무 막 모형에서 고무 막을 아래로 당기면 풍선(폐)이 부풀어요."),
        ce(.middle, "동물과 에너지", ["콩팥의 오줌 생성", "여과·재흡수·분비"], "콩팥의 네프론에서 오줌이 만들어져요. 사구체에서 보먼주머니로 크기가 작은 물질이 여과되고, 세뇨관에서 포도당·아미노산 전부와 물·무기염류 대부분이 모세 혈관으로 재흡수되며, 남은 노폐물 일부는 모세 혈관에서 세뇨관으로 분비돼요. 단백질이 분해될 때 생긴 암모니아는 간에서 독성이 약한 요소로 바뀌어 오줌으로 나가요.\n예: 건강한 사람의 오줌에는 단백질과 포도당이 없어요."),

        ce(.middle, "자극과 반응", ["눈의 구조", "시각의 전달 경로"], "빛은 각막 → 수정체 → 유리체 → 망막으로 전달되고, 망막의 시각 세포에서 받아들인 자극이 시각 신경을 통해 대뇌로 전달돼요. 홍채는 동공의 크기를 조절해 들어오는 빛의 양을 조절하고(밝으면 동공이 작아짐), 섬모체는 수정체 두께를 조절해요(가까운 곳을 볼 때 두꺼워짐).\n예: 어두운 극장에 들어가면 동공이 커져요."),
        ce(.middle, "자극과 반응", ["중추 신경계", "뇌와 척수"], "중추 신경계는 뇌와 척수로 이루어져요. 대뇌는 감각·기억·판단 등 고등 정신 활동, 소뇌는 몸의 균형 유지, 간뇌는 체온과 혈당량 등 항상성 조절, 중간뇌는 안구 운동과 동공 크기 조절, 연수는 심장 박동·호흡 운동·소화 운동 조절을 맡아요. 척수는 뇌와 몸 사이의 신호 전달 통로예요.\n예: 술에 취하면 비틀거리는 것은 알코올이 소뇌의 기능을 떨어뜨리기 때문이에요."),
        ce(.middle, "자극과 반응", ["무조건 반사", "reflex"], "대뇌의 판단을 거치지 않고 척수, 연수, 중간뇌가 중추가 되어 일어나는 빠른 반응이에요. 반응이 빨라서 위험한 상황에서 몸을 보호하는 데 중요해요.\n예: 뜨거운 물체에 손이 닿으면 손을 떼는 것(척수), 무릎 반사(척수), 재채기와 기침(연수), 밝은 빛에서 동공이 작아지는 것(중간뇌)"),
        ce(.middle, "자극과 반응", ["호르몬", "내분비계"], "내분비샘에서 만들어져 혈액으로 분비되고, 특정한 표적 기관에만 작용하는 화학 물질이에요. 적은 양으로 큰 효과를 내고, 신경보다 반응은 느리지만 효과가 오래 지속돼요. 너무 많거나 적게 분비되면 병이 생겨요.\n예: 이자의 인슐린은 혈당량을 낮추고, 갑상샘의 티록신은 세포 호흡을 촉진하며, 뇌하수체의 생장 호르몬은 몸의 생장을 촉진해요."),

        ce(.middle, "생식과 유전", ["체세포 분열", "mitosis", "염색체"], "몸을 구성하는 세포가 둘로 나뉘는 분열로, 간기 → 전기 → 중기 → 후기 → 말기를 거쳐 염색체 수와 유전 정보가 같은 딸세포 2개가 생겨요. 생장과 재생이 일어나요. 사람의 체세포에는 46개(23쌍)의 염색체가 있고, 그중 22쌍은 상염색체, 1쌍은 성염색체(남자 XY, 여자 XX)예요.\n예: 양파 뿌리 끝의 생장점에서 체세포 분열을 관찰할 수 있어요."),
        ce(.middle, "생식과 유전", ["감수 분열", "meiosis"], "생식세포(정자, 난자)를 만들 때 일어나는 분열로, 연속 두 번 분열하여 4개의 딸세포가 생기고 염색체 수가 체세포의 절반이 돼요. 감수 1분열에서 상동 염색체가 분리되어 염색체 수가 반으로 줄고, 감수 2분열에서 염색 분체가 분리돼요.\n예: 사람의 정자와 난자는 염색체를 23개씩 가지고, 수정되면 수정란은 다시 46개가 돼요."),
        ce(.middle, "생식과 유전", ["멘델의 유전 법칙", "우열의 원리·분리의 법칙·독립의 법칙"], "멘델은 완두 교배 실험으로 유전 원리를 밝혔어요. 순종끼리 교배한 잡종 1대에서는 우성 형질만 나타나고(우열의 원리), 잡종 1대를 자가 수분한 잡종 2대에서는 우성 : 열성 = 3 : 1로 나타나요(분리의 법칙). 두 쌍의 형질은 서로 영향을 주지 않고 독립적으로 유전되어 9 : 3 : 3 : 1로 나타나요(독립의 법칙).\n예: 둥근 완두(RR) × 주름진 완두(rr) → 잡종 1대 Rr은 모두 둥근 완두"),
        ce(.middle, "생식과 유전", ["사람의 유전", "ABO식 혈액형 유전"], "사람은 한 세대가 길고 자손 수가 적으며 교배 실험이 불가능해서 가계도 조사, 쌍둥이 연구, 집단 조사로 유전을 연구해요. ABO식 혈액형은 대립 유전자 A, B, O로 결정되며, A와 B는 O에 대해 우성이고 A와 B 사이에는 우열이 없어요. 적록 색맹처럼 X 염색체에 있는 유전자에 의한 형질은 남녀에 따라 나타나는 빈도가 달라요(반성 유전).\n예: 유전자형 AO인 아버지와 BO인 어머니 사이에서는 A형, B형, AB형, O형 자녀가 모두 태어날 수 있어요."),

        ce(.middle, "지권의 변화", ["지구 내부 구조", "지각·맨틀·외핵·내핵"], "지진파를 분석하여 지구 내부를 지각, 맨틀, 외핵, 내핵으로 구분해요. 지각은 대륙 지각(평균 약 35km)과 해양 지각(약 5km)으로 나뉘고, 맨틀은 깊이 약 2900km까지로 지구 부피의 약 80%를 차지해요. 외핵(약 2900~5100km)은 액체 상태, 내핵(약 5100~6400km)은 고체 상태로 추정돼요.\n예: S파가 외핵을 통과하지 못한다는 사실에서 외핵이 액체임을 알 수 있어요."),
        ce(.middle, "지권의 변화", ["암석의 순환", "화성암·퇴적암·변성암"], "화성암은 마그마가 식어 굳은 암석(빨리 식으면 결정이 작은 현무암, 천천히 식으면 결정이 큰 화강암), 퇴적암은 퇴적물이 다져지고 굳어진 암석(사암, 셰일, 석회암 - 층리와 화석이 나타남), 변성암은 암석이 높은 열과 압력을 받아 성질이 변한 암석(편마암, 대리암)이에요. 암석은 환경에 따라 서로 다른 암석으로 계속 변해요.\n예: 석회암이 열과 압력을 받으면 대리암이 돼요."),
        ce(.middle, "지권의 변화", ["판의 경계", "지진대와 화산대"], "지구의 겉 부분(암석권)은 크고 작은 여러 개의 판으로 나뉘어 있고, 판들은 1년에 수 cm씩 움직여요. 판과 판이 만나는 경계에서 지진과 화산 활동이 활발하게 일어나기 때문에 지진대와 화산대는 판의 경계와 거의 일치해요.\n예: 태평양 둘레의 환태평양 조산대(불의 고리)는 지진과 화산이 가장 많이 일어나는 곳이에요."),
        ce(.middle, "기권과 날씨", ["기권의 층상 구조", "대류권·성층권·중간권·열권"], "기권은 높이에 따른 기온 변화로 4개 층으로 나뉘어요. 대류권(지표~약 11km)은 높이 올라갈수록 기온이 낮아지고 기상 현상이 나타나요. 성층권(~약 50km)은 오존층이 자외선을 흡수해 위로 갈수록 기온이 높아요. 중간권(~약 80km)은 대류는 있지만 수증기가 거의 없어 기상 현상이 없고 유성이 보여요. 열권은 공기가 매우 희박하고 오로라가 나타나요.\n예: 장거리 비행기는 대기가 안정한 성층권 아래쪽을 날아요."),
        ce(.middle, "기권과 날씨", ["온실 효과", "복사 평형", "지구 온난화"], "지구는 흡수하는 태양 복사 에너지양과 방출하는 지구 복사 에너지양이 같은 복사 평형 상태예요. 대기 중의 수증기, 이산화 탄소, 메테인 같은 온실 기체가 지표에서 방출되는 지구 복사 에너지를 흡수했다가 다시 지표로 방출해 지구를 따뜻하게 유지하는 현상을 온실 효과라고 해요. 온실 기체가 늘어나 지구의 평균 기온이 높아지는 현상이 지구 온난화예요.\n예: 대기가 없는 달은 낮과 밤의 온도 차가 매우 커요."),
        ce(.middle, "기권과 날씨", ["포화 수증기량", "이슬점과 상대 습도"], "포화 수증기량은 포화 상태의 공기 1kg에 들어 있는 수증기량(g/kg)으로, 기온이 높을수록 커요. 공기가 냉각되어 포화 상태가 되는 온도를 이슬점이라고 해요. 상대 습도(%) = 현재 수증기량 ÷ 현재 기온의 포화 수증기량 × 100이에요. 상승하는 공기는 단열 팽창으로 온도가 낮아져 이슬점에 이르면 구름이 생겨요.\n예: 포화 수증기량이 14.7g/kg인 20°C 공기에 수증기가 7.6g/kg 있으면 상대 습도는 약 52%이고 이슬점은 10°C예요."),
        ce(.middle, "기권과 날씨", ["기단과 전선", "한랭 전선과 온난 전선"], "기단은 기온과 습도 같은 성질이 비슷한 큰 공기 덩어리이고, 성질이 다른 두 기단의 경계면이 지표와 만나는 선을 전선이라고 해요. 한랭 전선은 찬 공기가 따뜻한 공기 아래로 파고들어 적운형 구름과 좁은 지역의 소나기를, 온난 전선은 따뜻한 공기가 찬 공기 위로 올라가 층운형 구름과 넓은 지역의 지속적인 비를 만들어요.\n예: 우리나라 겨울은 춥고 건조한 시베리아 기단, 여름은 덥고 습한 북태평양 기단의 영향을 받아요."),
        ce(.middle, "수권과 해수의 순환", ["해수의 층상 구조", "혼합층·수온 약층·심해층", "염분"], "해수는 깊이에 따른 수온 변화로 3개 층으로 나뉘어요. 혼합층은 태양 에너지로 데워지고 바람에 의해 섞여 수온이 거의 일정한 층, 수온 약층은 깊어질수록 수온이 급격히 낮아지는 매우 안정한 층, 심해층은 수온이 낮고 거의 일정한 층이에요. 해수 1kg에 녹아 있는 염류의 양인 염분은 전 세계 평균 약 35psu예요.\n예: 바람이 강한 곳일수록 혼합층이 두꺼워져요."),

        ce(.middle, "태양계", ["태양의 표면과 대기", "흑점"], "태양의 표면을 광구라고 하며 온도는 약 6000°C예요. 광구에는 주위보다 온도가 낮아 어둡게 보이는 흑점과, 대류 때문에 생기는 쌀알 무늬가 있어요. 흑점이 동쪽에서 서쪽으로 이동하는 것으로 태양이 자전함을 알 수 있어요. 대기에는 채층, 코로나(약 100만 °C 이상), 홍염, 플레어가 있어요.\n예: 흑점 수가 많을 때 태양 활동이 활발해져 오로라, 자기 폭풍, 통신 장애가 잘 일어나요."),
        ce(.middle, "태양계", ["지구형 행성과 목성형 행성", "행성의 분류"], "지구형 행성(수성, 금성, 지구, 화성)은 질량과 반지름이 작고 평균 밀도가 크며, 단단한 암석 표면을 가지고 위성이 없거나 적어요. 목성형 행성(목성, 토성, 천왕성, 해왕성)은 질량과 반지름이 크고 평균 밀도가 작으며, 주로 기체로 이루어져 있고 위성이 많고 고리가 있어요.\n예: 토성은 평균 밀도가 물(1g/cm³)보다 작아요."),
        ce(.middle, "별과 우주", ["연주 시차", "annual parallax", "파섹"], "지구가 태양을 공전하기 때문에 6개월 간격으로 별을 관측하면 생기는 시차의 1/2이에요. 연주 시차는 별까지의 거리에 반비례해서, 거리(pc) = 1 ÷ 연주 시차(″)예요. 1pc(파섹)은 연주 시차가 1″인 별까지의 거리로 약 3.26광년이에요.\n예: 연주 시차가 0.1″인 별까지의 거리는 10pc, 약 32.6광년이에요."),
        ce(.middle, "별과 우주", ["별의 등급", "겉보기 등급과 절대 등급"], "별의 밝기는 등급으로 나타내며, 등급이 작을수록 밝아요. 1등급 차이는 밝기가 약 2.5배, 5등급 차이는 정확히 100배예요. 겉보기 등급은 눈에 보이는 밝기, 절대 등급은 별을 10pc 거리에 두었다고 가정했을 때의 밝기예요. 별의 색은 표면 온도에 따라 파란색(고온) → 흰색 → 노란색 → 붉은색(저온)으로 달라져요.\n예: 겉보기 등급 − 절대 등급 > 0이면 그 별은 10pc보다 멀리 있어요."),
        ce(.middle, "별과 우주", ["우리은하", "Milky Way", "은하수"], "태양계가 속해 있는 은하로, 수천억 개의 별이 모인 막대 나선 은하예요. 지름은 약 10만 광년이고, 태양계는 은하 중심에서 약 2만 6천 광년 떨어진 나선팔에 있어요. 우리은하 안에는 별의 집단인 성단과, 가스와 먼지로 이루어진 성운이 있어요. 지구에서 우리은하의 일부를 보면 띠 모양의 은하수로 보여요.\n예: 여름철 궁수자리 방향이 우리은하의 중심 방향이라 은하수가 가장 밝고 두껍게 보여요."),

        // MARK: - 고등학교

        ce(.high, "역학과 에너지", ["가속도 법칙", "뉴턴 운동 제2법칙", "등가속도 운동"], "물체의 가속도는 알짜힘에 비례하고 질량에 반비례해요. F = ma이고, 1N은 질량 1kg인 물체에 1m/s²의 가속도를 생기게 하는 힘이에요(1N = 1kg·m/s²). 가속도가 일정한 등가속도 직선 운동에서는 v = v₀ + at, s = v₀t + ½at², v² − v₀² = 2as가 성립해요.\n예: 질량 2kg인 물체에 6N의 알짜힘이 작용하면 가속도는 3m/s²이고, 정지 상태에서 출발해 2초 뒤 속도는 6m/s예요."),
        ce(.high, "역학과 에너지", ["운동량과 충격량", "운동량 보존 법칙", "momentum"], "운동량은 질량 × 속도(p = mv, 단위 kg·m/s)이고, 충격량은 힘 × 작용 시간(I = FΔt, 단위 N·s)이며, 물체가 받은 충격량은 운동량의 변화량과 같아요. 외력이 작용하지 않으면 충돌 전후 물체들의 운동량의 총합은 보존돼요.\n예: 에어백은 충돌 시간을 늘려 사람이 받는 힘을 줄여요. 3m/s로 움직이는 1kg 수레가 정지한 2kg 수레와 충돌해 함께 움직이면 속도는 1m/s예요."),
        ce(.high, "역학과 에너지", ["열역학 제1법칙", "열기관과 열효율"], "기체에 가한 열량은 기체의 내부 에너지 증가량과 기체가 외부에 한 일의 합과 같아요. Q = ΔU + W이고, 이는 열을 포함한 에너지 보존 법칙이에요. 열기관의 열효율은 e = W/Q₁ = 1 − Q₂/Q₁인데, 열역학 제2법칙에 따라 열효율이 100%인 열기관은 만들 수 없어요.\n예: 고열원에서 400J을 흡수하고 저열원으로 300J을 방출하는 열기관은 100J의 일을 하고 열효율은 25%예요."),
        ce(.high, "역학과 에너지", ["특수 상대성 이론", "special relativity"], "아인슈타인(1905)이 제안한 이론으로, 모든 관성 좌표계에서 물리 법칙은 같고(상대성 원리), 진공에서 빛의 속력은 관찰자나 광원의 운동과 관계없이 일정하다(광속 불변 원리)는 두 가정에서 출발해요. 그 결과 움직이는 시계가 느리게 가는 시간 지연, 운동 방향으로 길이가 짧아지는 길이 수축, 동시성의 상대성이 나타나요.\n예: 대기 상층에서 생긴 뮤온은 수명이 매우 짧지만 시간 지연 덕분에 지표까지 도달해요."),
        ce(.high, "역학과 에너지", ["질량·에너지 등가", "E = mc²", "질량 결손"], "질량과 에너지는 서로 바뀔 수 있으며 E = mc²의 관계가 있어요(c ≈ 3 × 10⁸ m/s). 핵분열이나 핵융합에서 반응 후 질량의 합이 줄어드는데, 이 줄어든 질량(질량 결손)만큼 에너지가 방출돼요.\n예: 질량 1g이 모두 에너지로 바뀌면 약 9 × 10¹³ J이 나와요. 원자력 발전은 우라늄 핵분열, 태양은 수소 핵융합의 질량 결손을 이용해요."),

        ce(.high, "물질과 전자기장", ["전기장", "electric field"], "전하 주위에서 다른 전하에 전기력이 작용하는 공간이에요. 전기장의 세기는 E = F/q(단위 N/C)이고, 점전하 Q로부터 거리 r인 곳에서 E = kQ/r²이에요(k ≈ 9 × 10⁹ N·m²/C²). 두 점전하 사이의 전기력은 F = kq₁q₂/r²으로 거리의 제곱에 반비례해요(쿨롱 법칙). 전기력선은 (+)전하에서 나와 (−)전하로 들어가요.\n예: 두 전하 사이의 거리가 2배가 되면 전기력은 1/4이 돼요."),
        ce(.high, "물질과 전자기장", ["에너지 준위", "보어 원자 모형", "선 스펙트럼"], "원자 속 전자는 특정한 에너지 값만 가질 수 있는데, 이를 에너지 준위라고 해요(보어 모형). 전자가 높은 준위에서 낮은 준위로 전이할 때 두 준위의 에너지 차이만큼 빛(광자)을 방출하고, E = hf = hc/λ예요. 그래서 기체 원소는 불연속적인 선 스펙트럼을 나타내요.\n예: 수소 원자에서 전자가 n = 3에서 n = 2로 전이할 때 파장 약 656nm의 빨간색 빛을 방출해요(발머 계열)."),
        ce(.high, "물질과 전자기장", ["자기장", "magnetic field"], "자석이나 전류 주위에 자기력이 작용하는 공간으로, 세기의 단위는 T(테슬라)예요. 직선 도선 주위의 자기장 세기는 B = k × I/r(k = 2 × 10⁻⁷ T·m/A)로 전류에 비례하고 거리에 반비례해요. 솔레노이드 내부에는 균일한 자기장이 생기며, 단위 길이당 감은 수와 전류에 비례해요.\n예: 10A가 흐르는 긴 직선 도선에서 0.1m 떨어진 곳의 자기장은 2 × 10⁻⁵ T예요."),
        ce(.high, "물질과 전자기장", ["전자기 유도", "패러데이 법칙", "렌츠 법칙"], "코일을 통과하는 자기 선속이 변하면 코일에 유도 기전력이 생겨 유도 전류가 흘러요. 유도 기전력의 크기는 V = −N × ΔΦ/Δt로 감은 수와 자기 선속의 시간 변화율에 비례해요(패러데이 법칙). 유도 전류는 자기 선속의 변화를 방해하는 방향으로 흘러요(렌츠 법칙).\n예: 발전기, 교통 카드, 무선 충전기, 전기 기타 픽업, 금속 탐지기"),

        ce(.high, "파동과 정보 통신", ["파동의 간섭", "보강 간섭과 상쇄 간섭"], "두 파동이 겹칠 때 합성파의 변위는 각 파동 변위의 합이에요(중첩 원리). 마루와 마루가 만나 진폭이 커지면 보강 간섭, 마루와 골이 만나 진폭이 작아지면 상쇄 간섭이에요. 위상이 같은 두 파원에서 경로차가 반파장의 짝수 배(0, λ, 2λ…)이면 보강, 홀수 배(λ/2, 3λ/2…)이면 상쇄 간섭이 일어나요.\n예: 소음 제거 헤드폰(상쇄 간섭), 비눗방울의 무지갯빛, 영의 이중 슬릿 실험의 밝고 어두운 무늬"),
        ce(.high, "파동과 정보 통신", ["전반사", "total internal reflection", "굴절 법칙"], "빛이 굴절률이 큰 매질에서 작은 매질로 진행할 때, 입사각이 임계각보다 크면 빛이 모두 반사되는 현상이에요. 굴절 법칙은 n₁ sin θ₁ = n₂ sin θ₂이고, 임계각 θc는 sin θc = n₂/n₁을 만족해요. 굴절률은 n = c/v예요.\n예: 광섬유는 굴절률이 큰 코어를 굴절률이 작은 클래딩이 감싸고 있어 빛이 전반사하며 멀리 전달돼요. 다이아몬드가 반짝이는 것도 전반사 때문이에요."),
        ce(.high, "파동과 정보 통신", ["광전 효과", "photoelectric effect", "광자"], "금속 표면에 문턱 진동수 이상의 빛을 비추면 전자(광전자)가 튀어나오는 현상이에요. 문턱 진동수보다 낮은 빛은 아무리 세게 비춰도 전자가 나오지 않아요. 아인슈타인은 빛이 E = hf의 에너지를 가진 광자로 이루어졌다고 설명했고(h = 6.63 × 10⁻³⁴ J·s), 광전자의 최대 운동 에너지는 hf − W(일함수)예요. 빛의 입자성을 보여 주는 현상이에요.\n예: 디지털카메라의 이미지 센서(CCD, CMOS), 태양 전지"),

        ce(.high, "화학의 첫걸음", ["몰", "mole", "아보가드로수"], "입자 6.02 × 10²³개의 묶음을 1몰(mol)이라고 하고, 이 수를 아보가드로수라고 해요. 물질 1몰의 질량은 화학식량에 g을 붙인 값이고, 0°C·1기압에서 기체 1몰의 부피는 종류에 관계없이 약 22.4L예요.\n예: 물(H₂O, 분자량 18) 36g은 2몰이고, 물 분자 1.204 × 10²⁴개가 들어 있어요. 0°C·1기압에서 산소 기체 11.2L는 0.5몰이에요."),
        ce(.high, "화학의 첫걸음", ["화학 반응식의 양적 관계", "계수비와 몰비", "몰 농도"], "화학 반응식의 계수비는 반응하거나 생성되는 물질의 몰비와 같고, 같은 온도·압력의 기체라면 부피비와도 같아요. 하지만 질량비와는 다르므로 질량은 몰수 × 몰 질량으로 계산해요. 용액의 몰 농도(M)는 용액 1L에 녹아 있는 용질의 몰수예요.\n예: 2H₂ + O₂ → 2H₂O에서 수소 4g(2몰)과 산소 32g(1몰)이 반응하면 물 36g(2몰)이 생겨요."),

        ce(.high, "원자와 화학 결합", ["동위 원소", "isotope", "질량수"], "양성자 수(원자 번호)는 같지만 중성자 수가 달라 질량수가 다른 원소예요. 질량수 = 양성자 수 + 중성자 수예요. 동위 원소는 화학적 성질이 거의 같고, 원자량은 동위 원소의 존재 비율을 고려한 평균값이에요.\n예: 염소는 ³⁵Cl(약 75%)과 ³⁷Cl(약 25%)이 있어 평균 원자량이 35 × 0.75 + 37 × 0.25 = 35.5예요. 방사성 동위 원소 ¹⁴C는 연대 측정에 쓰여요."),
        ce(.high, "원자와 화학 결합", ["전자 배치", "쌓음 원리·파울리 배타 원리·훈트 규칙"], "바닥상태 원자의 전자는 에너지가 낮은 오비탈부터 채워져요(쌓음 원리: 1s → 2s → 2p → 3s → 3p → 4s → 3d). 한 오비탈에는 스핀 방향이 반대인 전자가 최대 2개까지 들어가고(파울리 배타 원리), 에너지가 같은 오비탈에는 홀전자 수가 최대가 되도록 배치돼요(훈트 규칙).\n예: 산소(O)는 1s² 2s² 2p⁴로 홀전자가 2개, 원자가 전자가 6개예요."),
        ce(.high, "원자와 화학 결합", ["주기적 성질", "원자 반지름·이온화 에너지·전기 음성도"], "같은 주기에서 원자 번호가 커질수록 유효 핵전하가 증가해 원자 반지름은 작아지고, 이온화 에너지와 전기 음성도는 대체로 커져요. 같은 족에서 아래로 갈수록 전자 껍질 수가 늘어 원자 반지름은 커지고, 이온화 에너지와 전기 음성도는 작아져요. 전기 음성도가 가장 큰 원소는 플루오린(F, 4.0)이에요.\n예: 2주기에서 이온화 에너지는 Be > B, N > O로 예외가 나타나요."),
        ce(.high, "원자와 화학 결합", ["이온 결합", "ionic bond"], "금속 원소의 양이온과 비금속 원소의 음이온이 정전기적 인력으로 결합하는 것이에요. 이온 결합 물질은 이온들이 규칙적으로 배열된 결정을 이루며, 녹는점이 높고 단단하지만 힘을 받으면 쉽게 부서져요. 고체에서는 전기가 통하지 않지만 녹이거나 물에 녹이면 전기가 통해요. 이온의 전하량이 클수록, 이온 사이 거리가 짧을수록 결합력이 강해요.\n예: 녹는점은 NaCl 약 801°C, MgO 약 2800°C예요."),
        ce(.high, "원자와 화학 결합", ["공유 결합", "covalent bond"], "비금속 원자들이 서로 전자쌍을 내놓아 공유하며 결합하는 것이에요. 공유하는 전자쌍의 수에 따라 단일 결합, 2중 결합, 3중 결합이 있고, 결합한 원자들은 대부분 비활성 기체와 같은 전자 배치(옥텟)를 이뤄요. 전기 음성도가 다른 원자 사이의 공유 결합은 극성 공유 결합이에요.\n예: H₂(단일 결합), O₂(2중 결합), N₂(3중 결합), H₂O(극성 공유 결합)"),
        ce(.high, "원자와 화학 결합", ["분자 구조", "전자쌍 반발 이론", "극성 분자"], "중심 원자 주위의 전자쌍들은 서로 반발해 가능한 한 멀리 떨어지려 하기 때문에 분자의 모양이 정해져요. 비공유 전자쌍은 공유 전자쌍보다 반발력이 커서 결합각을 줄여요. 분자의 모양이 대칭이면 결합에 극성이 있어도 무극성 분자가 돼요.\n예: CO₂ 직선형 180°(무극성), BF₃ 평면 삼각형 120°, CH₄ 정사면체 109.5°, NH₃ 삼각뿔 107°, H₂O 굽은 형 104.5°(극성)"),

        ce(.high, "역동적인 화학 반응", ["화학 평형", "르샤틀리에 원리", "평형 상수"], "가역 반응에서 정반응 속도와 역반응 속도가 같아져 겉보기에 변화가 없는 상태로, 반응이 계속 일어나는 동적 평형이에요. aA + bB ⇌ cC + dD의 평형 상수는 K = [C]ᶜ[D]ᵈ/[A]ᵃ[B]ᵇ예요. 평형 상태에 농도·압력·온도 변화를 주면 그 변화를 줄이는 방향으로 평형이 이동해요(르샤틀리에 원리).\n예: N₂ + 3H₂ ⇌ 2NH₃에서 압력을 높이면 기체 몰수가 적은 암모니아 쪽으로 평형이 이동해요."),
        ce(.high, "역동적인 화학 반응", ["pH", "수소 이온 농도 지수", "브뢴스테드·로리 산 염기"], "수용액의 액성을 나타내는 값으로 pH = −log[H₃O⁺]예요. 25°C에서 물의 이온화 상수 Kw = [H₃O⁺][OH⁻] = 1.0 × 10⁻¹⁴이므로 pH + pOH = 14이고, pH 7이 중성, 7보다 작으면 산성, 크면 염기성이에요. pH가 1 작아지면 [H₃O⁺]는 10배 커져요. 브뢴스테드·로리 정의에서 산은 H⁺를 내놓는 물질, 염기는 H⁺를 받는 물질이에요.\n예: [H₃O⁺] = 1 × 10⁻³ M인 용액의 pH는 3이에요. 위액은 약 pH 2, 혈액은 약 pH 7.4예요."),
        ce(.high, "역동적인 화학 반응", ["중화 반응", "neutralization", "중화 적정"], "산의 H⁺(H₃O⁺)와 염기의 OH⁻가 1 : 1의 몰비로 반응하여 물이 생기는 반응이에요(H⁺ + OH⁻ → H₂O). 이때 열이 방출돼요(중화열). 완전히 중화되려면 산이 내놓는 H⁺의 몰수와 염기가 내놓는 OH⁻의 몰수가 같아야 하므로 가수 × 몰 농도 × 부피가 같아요(nMV = n′M′V′).\n예: 0.1M HCl 20mL를 완전히 중화하려면 0.2M NaOH 10mL가 필요해요."),
        ce(.high, "역동적인 화학 반응", ["산화 환원 반응", "redox reaction", "산화수"], "산화는 전자를 잃거나 산화수가 증가하는 반응이고, 환원은 전자를 얻거나 산화수가 감소하는 반응이에요. 한 물질이 잃은 전자를 다른 물질이 얻으므로 산화와 환원은 항상 동시에 일어나요. 다른 물질을 산화시키고 자신은 환원되는 물질을 산화제, 그 반대를 환원제라고 해요. 화합물에서 산화수는 보통 O는 −2, H는 +1이에요.\n예: Zn + Cu²⁺ → Zn²⁺ + Cu에서 아연은 산화, 구리 이온은 환원돼요. KMnO₄에서 Mn의 산화수는 +7이에요."),
        ce(.high, "역동적인 화학 반응", ["반응 속도", "활성화 에너지", "촉매"], "단위 시간 동안 반응물이나 생성물의 농도가 변하는 정도(단위 M/s)예요. 반응이 일어나려면 입자들이 활성화 에너지 이상의 에너지로 알맞은 방향으로 충돌해야 해요. 농도가 클수록, 온도가 높을수록, 고체의 표면적이 넓을수록 반응 속도가 빨라지고, 촉매는 활성화 에너지를 낮춰 반응 속도를 빠르게 해요(반응열은 변하지 않음).\n예: 음식을 냉장고에 넣으면 부패 속도가 느려지고, 몸속 효소는 생체 촉매예요."),

        ce(.high, "세포와 유전", ["세포 소기관", "organelle", "원핵세포와 진핵세포"], "진핵세포 안에서 특정 기능을 하는 구조물이에요. 핵은 DNA를 보관하고, 리보솜은 단백질을 합성하며, 소포체와 골지체는 단백질을 운반·가공·분비해요. 미토콘드리아는 세포 호흡으로 ATP를 만들고, 엽록체(식물)는 광합성을 하며, 리소좀은 세포 내 소화를 담당해요. 원핵세포(세균)는 핵막과 막으로 된 세포 소기관이 없지만 리보솜은 있어요.\n예: 이자 세포처럼 단백질을 많이 분비하는 세포에는 소포체와 골지체가 발달해 있어요."),
        ce(.high, "세포와 유전", ["세포막을 통한 물질 이동", "확산·삼투·능동 수송"], "세포막은 인지질 2중층에 단백질이 박혀 있는 구조(유동 모자이크 모델)로, 물질을 선택적으로 통과시켜요. 확산은 농도가 높은 곳에서 낮은 곳으로 물질이 이동하는 것, 삼투는 세포막을 경계로 물이 용질 농도가 낮은 쪽에서 높은 쪽으로 이동하는 것, 능동 수송은 ATP를 써서 농도가 낮은 쪽에서 높은 쪽으로 물질을 옮기는 것이에요.\n예: 적혈구를 증류수에 넣으면 물이 들어가 터지고, 신경 세포의 Na⁺-K⁺ 펌프는 능동 수송이에요."),
        ce(.high, "세포와 유전", ["DNA 구조", "이중 나선", "샤가프 법칙"], "DNA는 뉴클레오타이드(인산 + 디옥시리보스 + 염기)가 길게 연결된 두 가닥이 꼬인 이중 나선 구조예요(왓슨·크릭, 1953). 두 가닥은 방향이 반대(역평행)이며, 염기 A는 T와 2개, G는 C와 3개의 수소 결합으로 상보적으로 결합해요. 그래서 이중 가닥 DNA에서 A = T, G = C의 비율이 성립해요(샤가프 법칙).\n예: 어떤 DNA에서 A가 20%이면 T는 20%, G와 C는 각각 30%예요."),
        ce(.high, "세포와 유전", ["DNA 복제", "반보존적 복제"], "DNA는 세포 분열 전(S기)에 복제되는데, 이중 나선이 풀린 뒤 각 가닥이 주형이 되어 새 가닥이 만들어지므로 새 DNA는 기존 가닥 하나와 새 가닥 하나로 이루어져요(반보존적 복제, 메셀슨·스탈 실험). DNA 중합 효소는 5′ → 3′ 방향으로만 합성해서, 선도 가닥은 연속적으로, 지연 가닥은 짧은 조각(오카자키 절편)으로 합성된 뒤 DNA 연결 효소로 이어져요.\n예: 헬리케이스가 이중 나선을 풀어 복제 분기점을 만들어요."),
        ce(.high, "세포와 유전", ["유전자 발현", "전사와 번역", "코돈"], "유전자의 정보에 따라 단백질이 만들어지는 과정이에요. 진핵세포의 핵에서 RNA 중합 효소가 DNA를 주형으로 mRNA를 합성하고(전사), 세포질의 리보솜에서 mRNA의 코돈(염기 3개)에 맞는 아미노산을 tRNA가 운반해 단백질을 합성해요(번역). 개시 코돈은 AUG(메싸이오닌), 종결 코돈은 UAA, UAG, UGA예요.\n예: DNA 주형 가닥의 TAC → mRNA의 AUG → 메싸이오닌"),
        ce(.high, "세포와 유전", ["유전자 돌연변이", "염색체 이상"], "DNA 염기 서열이 바뀌어 생기는 유전자 돌연변이와 염색체의 수나 구조가 바뀌는 염색체 이상이 있어요. 구조 이상에는 결실, 중복, 역위, 전좌가 있고, 수 이상은 감수 분열 때 염색체가 제대로 분리되지 않아(비분리) 생겨요.\n예: 낫 모양 적혈구 빈혈증은 헤모글로빈 유전자의 염기 하나가 바뀌어 글루탐산이 발린으로 바뀐 것이고, 다운 증후군은 21번 염색체가 3개(총 47개), 터너 증후군은 성염색체가 X 하나(45, X)예요."),

        ce(.high, "항상성과 몸의 기능", ["항상성", "음성 피드백", "체온 조절"], "몸 안팎의 환경이 변해도 체온, 혈당량, 삼투압 등을 일정하게 유지하는 성질이에요. 간뇌의 시상 하부가 중추가 되어 신경과 호르몬으로 조절하며, 결과가 원인을 억제하는 음성 피드백이 중요해요. 체온이 낮아지면 피부 혈관 수축, 근육 떨림, 티록신 분비 증가가 일어나고, 혈장 삼투압이 높아지면 항이뇨 호르몬(ADH) 분비가 늘어 콩팥에서 물의 재흡수가 촉진돼요.\n예: 티록신이 많아지면 TSH 분비가 억제되어 티록신 분비가 다시 줄어요."),
        ce(.high, "항상성과 몸의 기능", ["혈당량 조절", "인슐린과 글루카곤"], "혈당량은 이자에서 분비되는 두 호르몬의 길항 작용으로 조절돼요. 혈당량이 높으면 β세포에서 인슐린이 분비되어 간에서 포도당을 글리코젠으로 합성하고 세포의 포도당 흡수를 촉진해 혈당량을 낮춰요. 혈당량이 낮으면 α세포에서 글루카곤이 분비되어 간의 글리코젠을 포도당으로 분해해 혈당량을 높여요.\n예: 1형 당뇨병은 인슐린이 분비되지 않아서, 2형 당뇨병은 세포가 인슐린에 잘 반응하지 않아서 생겨요."),
        ce(.high, "항상성과 몸의 기능", ["흥분의 전도", "활동 전위", "휴지 전위"], "자극을 받지 않은 뉴런은 세포막 안쪽이 바깥보다 음(−)전하를 띠는 분극 상태로, 휴지 전위는 약 −70mV예요. 자극을 받으면 Na⁺ 통로가 열려 Na⁺가 들어오며 탈분극이 일어나고(활동 전위, 약 +30mV까지), 이어서 K⁺가 빠져나가며 재분극돼요. 시냅스에서는 축삭 돌기 말단에서 분비된 신경 전달 물질에 의해 한 방향으로만 흥분이 전달돼요.\n예: 말이집 신경은 도약 전도를 해서 흥분 전도 속도가 빨라요."),
        ce(.high, "항상성과 몸의 기능", ["자율 신경계", "교감 신경과 부교감 신경"], "대뇌의 직접적인 명령 없이 내장 기관을 조절하는 말초 신경계로, 교감 신경과 부교감 신경이 같은 기관에 분포해 서로 반대로 작용해요(길항 작용). 교감 신경은 위급한 상황에서 심장 박동 촉진, 동공 확대, 기관지 확장, 소화 억제를 일으키고, 부교감 신경은 몸을 안정 상태로 되돌려요. 신경절 이후 뉴런 말단에서 교감 신경은 노르에피네프린, 부교감 신경은 아세틸콜린을 분비해요.\n예: 발표 직전에 가슴이 두근거리고 입이 마르는 것은 교감 신경의 작용이에요."),
        ce(.high, "항상성과 몸의 기능", ["면역", "특이적 방어와 비특이적 방어", "백신"], "비특이적 방어는 병원체 종류에 관계없이 일어나는 방어로 피부, 점막, 식균 작용, 염증 반응이 있어요. 특이적 방어에는 세포독성 T림프구가 감염된 세포를 직접 제거하는 세포성 면역과, B림프구가 형질 세포로 분화해 항체를 생산하는 체액성 면역이 있어요. 1차 면역 반응 때 생긴 기억 세포 덕분에 같은 항원이 다시 들어오면 빠르고 강한 2차 면역 반응이 일어나요.\n예: 백신은 기억 세포를 미리 만들어 두는 원리를 이용해요."),

        ce(.high, "생태계와 진화", ["개체군", "군집", "천이"], "개체군은 일정 지역에 사는 같은 종의 무리이고, 군집은 여러 개체군의 집합이에요. 개체군은 먹이·공간 부족 같은 환경 저항 때문에 실제로는 S자형 생장 곡선을 그리며, 환경 수용력에 이르면 더 늘지 않아요. 군집이 시간에 따라 변해 가는 것을 천이라고 하며, 1차 천이는 맨땅에서 지의류(개척자) → 초원 → 관목림 → 양수림 → 혼합림 → 음수림(극상) 순으로 진행돼요.\n예: 산불이 난 뒤 토양이 남은 곳에서 시작되는 천이는 2차 천이예요."),
        ce(.high, "생태계와 진화", ["에너지 흐름", "물질 순환", "에너지 효율"], "생태계에서 물질은 생물과 비생물 환경 사이를 순환하지만, 에너지는 태양에서 생산자 → 소비자로 한 방향으로 흐르다가 결국 열에너지로 생태계 밖으로 빠져나가요. 각 영양 단계에서 호흡 등으로 에너지가 소모되므로 상위 영양 단계로 갈수록 에너지양이 줄어 생태 피라미드를 이뤄요. 에너지 효율(%) = 현 영양 단계의 에너지양 ÷ 전 영양 단계의 에너지양 × 100이에요.\n예: 1차 소비자 100kcal, 2차 소비자 15kcal이면 2차 소비자의 에너지 효율은 15%예요."),
        ce(.high, "생태계와 진화", ["자연 선택설", "다윈의 진화론", "진화의 증거"], "다윈이 제시한 진화의 원리로, 생물은 살아남을 수 있는 것보다 많은 자손을 낳고(과잉 생산), 개체 사이에는 변이가 있으며, 환경에 유리한 변이를 가진 개체가 더 많이 살아남아 자손을 남겨(자연 선택) 그 형질이 집단에 퍼진다는 이론이에요. 진화의 증거로는 화석, 상동 기관, DNA 염기 서열의 유사성 등이 있어요.\n예: 항생제를 남용하면 내성 세균의 비율이 높아지고, 사람 팔·고래 가슴지느러미·박쥐 날개는 상동 기관이에요."),
        ce(.high, "생태계와 진화", ["하디·바인베르크 평형", "유전자풀", "대립 유전자 빈도"], "큰 집단, 무작위 교배, 돌연변이·이주·자연 선택이 없는 조건에서는 대립 유전자 빈도가 세대가 지나도 변하지 않아요. 대립 유전자 A, a의 빈도를 p, q라 하면 p + q = 1이고, 유전자형 빈도는 AA : Aa : aa = p² : 2pq : q²예요. 이 평형이 깨지면 집단이 진화하고 있는 것이에요.\n예: 열성 형질(aa)이 4% 나타나면 q = 0.2, p = 0.8이므로 보인자(Aa)는 2 × 0.8 × 0.2 = 32%예요."),

        ce(.high, "고체 지구", ["판 구조론", "plate tectonics", "해양저 확장설"], "지구 표면이 여러 개의 판(암석권)으로 이루어져 있고, 판이 연약권 위에서 이동하며 지진·화산·습곡 산맥 같은 지각 변동이 일어난다는 이론이에요. 베게너의 대륙 이동설 → 홈스의 맨틀 대류설 → 해양저 확장설(해령 양쪽 고지자기 줄무늬의 대칭, 해령에서 멀수록 해양 지각의 나이가 많음)을 거쳐 완성되었어요. 판을 움직이는 주된 힘은 섭입하는 판이 잡아당기는 힘, 해령에서 밀어내는 힘, 맨틀 대류예요.\n예: 하와이 열도는 거의 고정된 열점 위로 태평양판이 이동하며 만들어졌어요."),
        ce(.high, "고체 지구", ["판의 경계 유형", "발산형·수렴형·보존형 경계"], "발산형 경계는 판이 서로 멀어지는 곳으로 해령과 열곡대가 생겨요. 수렴형 경계는 판이 가까워지는 곳으로, 밀도가 큰 판이 섭입하면 해구·호상 열도·습곡 산맥이 생기고(섭입형), 대륙판끼리 충돌하면 거대한 습곡 산맥이 생겨요(충돌형). 보존형 경계는 판이 서로 어긋나는 곳으로 변환 단층이 나타나요.\n예: 대서양 중앙 해령·동아프리카 열곡대(발산형), 일본 해구·안데스산맥(섭입형), 히말라야산맥(충돌형), 산안드레아스 단층(보존형)"),
        ce(.high, "고체 지구", ["지질 시대", "geologic time scale", "표준 화석"], "지구 탄생(약 46억 년 전) 이후를 생물계의 큰 변화를 기준으로 선캄브리아 시대, 고생대, 중생대, 신생대로 나눠요. 고생대(약 5억 4천만 년 전부터)에는 삼엽충·갑주어가 번성했고 말기에 판게아가 형성되며 대멸종이 일어났어요. 중생대(약 2억 5천만 년 전부터)는 공룡·암모나이트·겉씨식물, 신생대(약 6600만 년 전부터)는 화폐석·매머드·속씨식물이 번성했어요.\n예: 삼엽충 화석이 나오면 그 지층은 고생대에 쌓였다고 판단해요(표준 화석)."),
        ce(.high, "고체 지구", ["절대 연령", "반감기", "방사성 동위 원소 연대 측정"], "방사성 동위 원소가 일정한 비율로 붕괴하는 성질을 이용해 암석이나 화석의 나이를 수치로 구한 것이에요. 모원소의 양이 처음의 절반으로 줄어드는 데 걸리는 시간을 반감기라고 하며, 반감기가 1번 지나면 1/2, 2번이면 1/4, 3번이면 1/8이 남아요. 지층의 선후 관계만 알려 주는 상대 연령과 구별돼요.\n예: 반감기가 1억 년인 원소의 모원소가 처음의 25%만 남았다면 암석의 나이는 2억 년이에요. ¹⁴C의 반감기는 약 5730년이에요."),

        ce(.high, "대기와 해양", ["대기 대순환", "해들리 순환", "무역풍과 편서풍"], "위도에 따른 에너지 불균형과 지구 자전 때문에 지구 전체 규모로 일어나는 대기의 순환이에요. 북반구와 남반구에 각각 3개의 순환 세포(해들리 순환 0~30°, 페렐 순환 30~60°, 극순환 60~90°)가 있고, 지표 부근에는 무역풍(저위도), 편서풍(중위도), 극동풍(고위도)이 불어요. 위도 30° 부근은 공기가 하강하는 중위도 고압대예요.\n예: 사하라 사막처럼 큰 사막이 위도 30° 부근에 많은 것은 하강 기류로 건조하기 때문이에요."),
        ce(.high, "대기와 해양", ["심층 순환", "열염 순환"], "수온과 염분 변화에 따른 밀도 차이로 일어나는 해수의 순환이에요. 극지방에서 해수가 냉각되고 결빙으로 염분이 높아지면 밀도가 커져 가라앉아 심층수가 되고, 저위도로 천천히 이동해요. 대표적으로 북대서양 심층수와 남극 저층수가 있어요. 표층 순환과 연결되어 전 지구를 도는 컨베이어 벨트처럼 열을 수송하며, 한 바퀴 도는 데 약 1000년 이상 걸려요.\n예: 그린란드 빙하가 녹아 담수가 유입되면 침강이 약해져 열 수송이 줄어들 수 있어요."),
        ce(.high, "대기와 해양", ["엘니뇨", "El Niño", "라니냐", "엔소"], "평소보다 무역풍이 약해져 서태평양의 따뜻한 해수가 동쪽으로 이동하고 동태평양 적도 부근의 용승이 약해져, 동태평양의 표층 수온이 평년보다 높아지는 현상이에요. 반대로 무역풍이 강해져 동태평양 수온이 낮아지는 현상은 라니냐예요. 엘니뇨·라니냐와 대기의 남방 진동을 묶어 엔소(ENSO)라고 해요.\n예: 엘니뇨 때 페루 연안은 홍수가 잦고 어획량이 줄며, 인도네시아·오스트레일리아는 가뭄과 산불이 늘어요."),
        ce(.high, "대기와 해양", ["태풍", "typhoon", "열대 저기압"], "북서태평양에서 발생해 중심 부근 최대 풍속이 17m/s 이상으로 발달한 열대 저기압이에요. 주로 위도 5~25°, 수온 약 27°C 이상인 해역에서 발생하며, 수증기가 응결할 때 방출하는 숨은열이 주된 에너지원이에요. 전선을 동반하지 않고, 중심에는 하강 기류로 맑은 태풍의 눈이 있어요. 북반구에서는 진행 방향의 오른쪽이 바람이 더 강한 위험 반원이에요.\n예: 태풍이 육지에 상륙하면 수증기 공급이 줄고 마찰이 커져 약해져요."),

        ce(.high, "우주", ["H-R도", "헤르츠스프룽·러셀도", "주계열성"], "가로축에 별의 표면 온도(분광형 O B A F G K M, 왼쪽이 고온), 세로축에 광도(또는 절대 등급)를 나타낸 그림이에요. 별의 약 90%는 왼쪽 위에서 오른쪽 아래로 이어지는 주계열성이고, 오른쪽 위에는 거성과 초거성, 왼쪽 아래에는 백색 왜성이 있어요. 표면 온도가 같다면 광도가 클수록 반지름이 커요.\n예: 태양은 분광형 G2, 표면 온도 약 5800K인 주계열성이에요."),
        ce(.high, "우주", ["별의 진화", "stellar evolution", "수소 핵융합"], "성운에서 원시별이 생기고, 중심에서 수소 핵융합 반응(수소 원자핵 4개 → 헬륨 원자핵 1개)이 시작되면 주계열성이 돼요. 태양 정도 질량의 별은 적색 거성을 거쳐 행성상 성운과 백색 왜성으로 일생을 마쳐요. 질량이 태양의 약 8배 이상인 별은 초거성이 되어 중심에 철까지 만든 뒤 초신성 폭발을 일으키고 중성자별이나 블랙홀이 돼요. 질량이 클수록 수명이 짧아요.\n예: 금이나 우라늄처럼 철보다 무거운 원소는 초신성 폭발이나 중성자별 충돌에서 만들어져요."),
